const tryLockCard = `-- name: TryLockCard :one
SELECT pg_try_advisory_xact_lock(hashtextextended($1::uuid::text, 1)) AS ok
`

func (q *Queries) TryLockCard(ctx context.Context, cardID uuid.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, tryLockCard, cardID)
	var ok bool
	err := row.Scan(&ok)
	return ok, err
}

const upsertMachineWait = `-- name: UpsertMachineWait :exec
INSERT INTO inbox_item (workspace_id, user_id, kind, text, runtime_id, cause)
VALUES ($1, $2, 'waiting_for_machine', $3, $4, $5)
ON CONFLICT (workspace_id, runtime_id, cause) WHERE kind = 'waiting_for_machine' AND resolved_at IS NULL DO NOTHING
`

type UpsertMachineWaitParams struct {
	WorkspaceID uuid.UUID  `json:"workspace_id"`
	UserID      uuid.UUID  `json:"user_id"`
	Text        string     `json:"text"`
	RuntimeID   *uuid.UUID `json:"runtime_id"`
	Cause       *string    `json:"cause"`
}

// One open item per machine and cause: later waits on it add nothing.
func (q *Queries) UpsertMachineWait(ctx context.Context, arg UpsertMachineWaitParams) error {
	_, err := q.db.Exec(ctx, upsertMachineWait,
		arg.WorkspaceID,
		arg.UserID,
		arg.Text,
		arg.RuntimeID,
		arg.Cause,
	)
	return err
}

const upsertStopDecision = `-- name: UpsertStopDecision :exec
INSERT INTO inbox_item (workspace_id, card_id, user_id, kind, text, cause, options, default_option, expires_at)
VALUES ($1, $2::uuid, $3, $4, $5, $6::text, $7::jsonb, $8, $9)
ON CONFLICT (workspace_id, card_id, cause) WHERE kind = 'needs_decision' AND resolved_at IS NULL
DO UPDATE SET text = EXCLUDED.text, options = EXCLUDED.options, default_option = EXCLUDED.default_option,
  expires_at = EXCLUDED.expires_at
`

type UpsertStopDecisionParams struct {
	WorkspaceID   uuid.UUID       `json:"workspace_id"`
	CardID        uuid.UUID       `json:"card_id"`
	UserID        uuid.UUID       `json:"user_id"`
	Kind          string          `json:"kind"`
	Text          string          `json:"text"`
	Cause         string          `json:"cause"`
	Options       json.RawMessage `json:"options"`
	DefaultOption string          `json:"default_option"`
	ExpiresAt     *time.Time      `json:"expires_at"`
}

// A study's stop is a decision: one open item per study and cause (a needs_decision
// item), carrying its options, its default and the moment the default applies.
func (q *Queries) UpsertStopDecision(ctx context.Context, arg UpsertStopDecisionParams) error {
	_, err := q.db.Exec(ctx, upsertStopDecision,
		arg.WorkspaceID,
		arg.CardID,
		arg.UserID,
		arg.Kind,
		arg.Text,
		arg.Cause,
		arg.Options,
		arg.DefaultOption,
		arg.ExpiresAt,
	)
	return err
}

const waitLockCard = `-- name: WaitLockCard :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::uuid::text, 1))
`

// The same lock as TryLockCard, waited for: the engine's write phase must not
// drop finished scoring because a short read phase holds the lock.
func (q *Queries) WaitLockCard(ctx context.Context, cardID uuid.UUID) error {
	_, err := q.db.Exec(ctx, waitLockCard, cardID)
	return err
}
